                    std::time::Instant::now() < deadline,
                    "{} was still held open for writing after 30s",
                    path.display()
                );
                std::thread::sleep(std::time::Duration::from_millis(5));
            }
            Err(error) => panic!("{} could not start: {error}", path.display()),
        }
    }
}

