            .expect("shutdown should finish without a live leg");
        timeout(Duration::from_secs(1), shutdown_notice.changed())
            .await
            .expect("websocket shutdown notice should be immediate")
            .unwrap();
        assert!(*shutdown_notice.borrow());
    }
}

